<?php

namespace App\Http\Controllers\Api\V1;

use App\Models\{AccountingCurrency, ApprovalRequest, Company, Product, ProductVariant, Supplier, SupplierContract, SupplierContractVersion, SupplierProduct, SupplierPurchasePriceList, SupplierPurchasePriceListItem};
use App\Services\{ApprovalService, AuditLogger, AuthorizationService, ProcurementNumberService};
use App\Support\TenantContext;
use Illuminate\Http\{JsonResponse, Request};
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\ValidationException;

final class SupplierCatalogController
{
    private function tenant(): string { return (string) app(TenantContext::class)->id(); }
    private function allow(Request $r, AuthorizationService $a, ?string $company = null): void { abort_unless($a->allows($r->user(), $this->tenant(), 'procurement.manage', $company), 403); }
    private function supplier(Request $r, Supplier $s, AuthorizationService $a, ?string $company = null): void
    {
        abort_unless($s->tenant_id === $this->tenant(), 404);
        $scope = $company ?: $s->company_id;
        $this->allow($r, $a, $scope);
        abort_unless($s->company_id === null || $scope === null || $s->company_id === $scope, 404);
    }
    public function summary(Request $r, AuthorizationService $a): JsonResponse
    {
        $company = $r->string('company_id')->toString() ?: null; $this->allow($r, $a, $company); $t = $this->tenant();
        $base = fn ($m) => $m::where('tenant_id',$t)->when($company,fn($q)=>$q->where('company_id',$company));
        return response()->json(['data'=>[
            'supplier_products'=>$base(SupplierProduct::class)->count(),
            'active_price_lists'=>$base(SupplierPurchasePriceList::class)->where('status','active')->count(),
            'active_contracts'=>$base(SupplierContract::class)->where('status','active')->count(),
            'pending_price_approvals'=>$base(SupplierPurchasePriceList::class)->where('status','pending_approval')->count(),
            'expiring_agreements'=>$base(SupplierContract::class)->where('status','active')->whereDate('ends_at','<=',now()->addDays(90))->count(),
            'unmapped_supplier_products'=>$base(SupplierProduct::class)->whereNull('variant_id')->count(),
        ]]);
    }
    public function products(Request $r, AuthorizationService $a): JsonResponse
    {
        $company = $r->string('company_id')->toString() ?: null; $this->allow($r,$a,$company); $t=$this->tenant();
        $q=SupplierProduct::where('tenant_id',$t)->with(['supplier','variant.product','currency'])->when($company,fn($x)=>$x->where('company_id',$company))
            ->when($r->filled('supplier_id'),fn($x)=>$x->where('supplier_id',$r->string('supplier_id')))
            ->when($r->filled('status'),fn($x)=>$x->where('status',$r->string('status')))
            ->when($r->filled('search'),function($x)use($r){$s=$r->string('search');$x->where(fn($w)=>$w->where('supplier_sku','ilike',"%{$s}%")->orWhere('supplier_name','ilike',"%{$s}%")->orWhere('supplier_barcode','ilike',"%{$s}%")->orWhereHas('supplier',fn($z)=>$z->where('name','ilike',"%{$s}%")));});
        $sort=in_array($r->string('sort')->toString(),['supplier_sku','supplier_name','status','created_at'],true)?$r->string('sort')->toString():'created_at';
        $page=$q->orderBy($sort,$r->string('direction')->toString()==='asc'?'asc':'desc')->paginate(min(max($r->integer('per_page',25),10),100));
        return response()->json(['data'=>$page]);
    }
    public function storeProduct(Request $r, AuthorizationService $a, AuditLogger $audit): JsonResponse
    {
        $d=$r->validate(['company_id'=>'required|uuid','supplier_id'=>'required|uuid','product_id'=>'nullable|uuid','variant_id'=>'nullable|uuid','catalog_reference'=>'nullable|string|max:120','supplier_sku'=>'required|string|max:160','supplier_name'=>'required|string|max:255','description'=>'nullable|string|max:5000','supplier_barcode'=>'nullable|string|max:160','brand'=>'nullable|string|max:160','model_number'=>'nullable|string|max:160','manufacturer_part_number'=>'nullable|string|max:160','packaging_information'=>'nullable|string|max:255','purchase_uom'=>'nullable|string|max:40','minimum_order_quantity'=>['nullable','regex:/^\\d+(\\.\\d{1,6})?$/'],'order_multiple'=>['nullable','regex:/^\\d+(\\.\\d{1,6})?$/'],'pack_size'=>['nullable','regex:/^\\d+(\\.\\d{1,6})?$/'],'standard_lead_time'=>'nullable|integer|min:0|max:3650','lead_time_unit'=>'nullable|string|max:20','availability_status'=>'nullable|in:available,temporarily_unavailable,discontinued','temporarily_unavailable_reason'=>'nullable|string|max:2000','expected_availability_date'=>'nullable|date','discontinued_date'=>'nullable|date','currency_id'=>'nullable|uuid','base_purchase_price'=>['nullable','regex:/^\\d+(\\.\\d{1,6})?$/'],'price_effective_from'=>'nullable|date','price_effective_to'=>'nullable|date|after_or_equal:price_effective_from','tax_code'=>'nullable|string|max:80']);
        $this->allow($r,$a,$d['company_id']); $t=$this->tenant();
        $supplier=Supplier::where('tenant_id',$t)->whereKey($d['supplier_id'])->where('status','active')->firstOrFail();
        abort_unless($supplier->company_id===null||$supplier->company_id===$d['company_id'],422,'Supplier is not available for this company.');
        if(!empty($d['variant_id'])){ $v=ProductVariant::where('tenant_id',$t)->whereKey($d['variant_id'])->where('is_active',true)->firstOrFail(); abort_unless(empty($d['product_id'])||$v->product_id===$d['product_id'],422,'Variant does not belong to product.'); $d['product_id']=$v->product_id; }
        if(!empty($d['product_id'])) abort_unless(Product::where('tenant_id',$t)->whereKey($d['product_id'])->exists(),404);
        abort_unless(!SupplierProduct::where('tenant_id',$t)->where('company_id',$d['company_id'])->where('supplier_id',$supplier->id)->where('supplier_sku',$d['supplier_sku'])->exists(),422,'Supplier SKU already exists in this company.');
        $p=SupplierProduct::create([...$d,'tenant_id'=>$t,'status'=>'active','availability_status'=>$d['availability_status']??'available','minimum_order_quantity'=>$d['minimum_order_quantity']??'0','order_multiple'=>$d['order_multiple']??'0','created_by'=>$r->user()->id]);
        $audit->record($r,'supplier_product.created',$t,$p,['company_id'=>$p->company_id,'supplier_id'=>$p->supplier_id]); return response()->json(['data'=>$p->load(['supplier','variant.product','currency'])],201);
    }
    public function updateProduct(Request $r, SupplierProduct $product, AuthorizationService $a, AuditLogger $audit): JsonResponse
    {
        abort_unless($product->tenant_id===$this->tenant(),404); $this->allow($r,$a,$product->company_id);
        $d=$r->validate(['supplier_name'=>'sometimes|required|string|max:255','description'=>'nullable|string|max:5000','supplier_barcode'=>'nullable|string|max:160','brand'=>'nullable|string|max:160','purchase_uom'=>'nullable|string|max:40','minimum_order_quantity'=>['nullable','regex:/^\\d+(\\.\\d{1,6})?$/'],'order_multiple'=>['nullable','regex:/^\\d+(\\.\\d{1,6})?$/'],'standard_lead_time'=>'nullable|integer|min:0','availability_status'=>'nullable|in:available,temporarily_unavailable,discontinued','status'=>'nullable|in:active,inactive']);
        if(isset($d['supplier_name']))$d['updated_by']=$r->user()->id; $product->update($d); $audit->record($r,'supplier_product.updated',$this->tenant(),$product); return response()->json(['data'=>$product->fresh(['supplier','variant.product','currency'])]);
    }
    public function priceLists(Request $r, AuthorizationService $a): JsonResponse
    {
        $company=$r->string('company_id')->toString()?:null;$this->allow($r,$a,$company);$q=SupplierPurchasePriceList::where('tenant_id',$this->tenant())->with(['supplier','currency'])->when($company,fn($x)=>$x->where('company_id',$company))->when($r->filled('supplier_id'),fn($x)=>$x->where('supplier_id',$r->string('supplier_id')))->latest(); return response()->json(['data'=>$q->paginate(min(max($r->integer('per_page',25),10),100))]);
    }
    public function storePriceList(Request $r, AuthorizationService $a, ProcurementNumberService $numbers, AuditLogger $audit): JsonResponse
    {
        $d=$r->validate(['company_id'=>'required|uuid','supplier_id'=>'required|uuid','name'=>'required|string|max:200','currency_id'=>'nullable|uuid','effective_from'=>'required|date','effective_to'=>'nullable|date|after_or_equal:effective_from','description'=>'nullable|string|max:4000','items'=>'required|array|min:1','items.*.supplier_product_id'=>'required|uuid','items.*.minimum_quantity'=>['required','regex:/^\\d+(\\.\\d{1,6})?$/'],'items.*.maximum_quantity'=>['nullable','regex:/^\\d+(\\.\\d{1,6})?$/'],'items.*.unit_price'=>['required','regex:/^\\d+(\\.\\d{1,6})?$/'],'items.*.purchase_uom'=>'nullable|string|max:40','items.*.tax_code'=>'nullable|string|max:80']);$this->allow($r,$a,$d['company_id']);$t=$this->tenant();$supplier=Supplier::where('tenant_id',$t)->whereKey($d['supplier_id'])->firstOrFail();abort_unless($supplier->company_id===null||$supplier->company_id===$d['company_id'],422);
        $ids=collect($d['items'])->pluck('supplier_product_id');abort_unless($ids->unique()->count()===$ids->count(),422,'A product may appear once per price list.');$products=SupplierProduct::where('tenant_id',$t)->where('company_id',$d['company_id'])->where('supplier_id',$supplier->id)->whereIn('id',$ids)->get()->keyBy('id');abort_unless($products->count()===$ids->count(),422,'Every price item must belong to the supplier and company.');
        foreach($d['items'] as $item){if($item['maximum_quantity']??null)abort_unless((float)$item['maximum_quantity']>=(float)$item['minimum_quantity'],422,'Maximum quantity must be greater than minimum quantity.');}
        $list=DB::transaction(function()use($d,$t,$r,$numbers,$products){$m=SupplierPurchasePriceList::create(['tenant_id'=>$t,'company_id'=>$d['company_id'],'supplier_id'=>$d['supplier_id'],'number'=>$numbers->makeFor('SPL',$t,$d['company_id'],null),'name'=>$d['name'],'currency_id'=>$d['currency_id']??null,'effective_from'=>$d['effective_from'],'effective_to'=>$d['effective_to']??null,'description'=>$d['description']??null,'created_by'=>$r->user()->id]);foreach($d['items'] as $i)SupplierPurchasePriceListItem::create([...$i,'tenant_id'=>$t,'price_list_id'=>$m->id]);return $m;});$audit->record($r,'supplier_price_list.created',$t,$list);return response()->json(['data'=>$list->load(['supplier','items.supplierProduct'])],201);
    }
    public function submitPriceList(Request $r,SupplierPurchasePriceList $list,ApprovalService $approval,AuditLogger $audit):JsonResponse
    {abort_unless($list->tenant_id===$this->tenant(),404);$this->allow($r,app(AuthorizationService::class),$list->company_id);abort_unless($list->status==='draft',422);$request=$approval->create(['tenant_id'=>$this->tenant(),'company_id'=>$list->company_id,'requester_id'=>$r->user()->id,'scenario'=>'supplier_price_list','amount'=>$list->items()->sum('unit_price'),'document_type'=>SupplierPurchasePriceList::class,'document_id'=>$list->id]);$list->update(['status'=>'pending_approval','approval_request_id'=>$request->id]);$audit->record($r,'supplier_price_list.submitted',$this->tenant(),$list);return response()->json(['data'=>$list->fresh()]);}
    public function activatePriceList(Request $r,SupplierPurchasePriceList $list,AuthorizationService $a,AuditLogger $audit):JsonResponse
    {abort_unless($list->tenant_id===$this->tenant(),404);$this->allow($r,$a,$list->company_id);abort_unless($list->status==='approved',422,'Only approved price lists can be activated.');$list->update(['status'=>'active','activated_by'=>$r->user()->id,'activated_at'=>now()]);$audit->record($r,'supplier_price_list.activated',$this->tenant(),$list);return response()->json(['data'=>$list]);}
    public function approvePriceList(Request $r,SupplierPurchasePriceList $list,ApprovalService $approval,AuditLogger $audit):JsonResponse
    {abort_unless($list->tenant_id===$this->tenant(),404);$this->allow($r,app(AuthorizationService::class),$list->company_id);abort_unless($list->status==='pending_approval'&&$list->approval_request_id,422);$d=$r->validate(['remarks'=>'nullable|string|max:2000']);$request=ApprovalRequest::findOrFail($list->approval_request_id);$result=$approval->decide($request,$r->user(),'approved',$d['remarks']??null);if($result->state==='approved')$list->update(['status'=>'approved','approved_by'=>$r->user()->id,'approved_at'=>now()]);$audit->record($r,'supplier_price_list.approval_decided',$this->tenant(),$list,['state'=>$result->state]);return response()->json(['data'=>$list->fresh()]);}
    public function resolvePrice(Request $r,SupplierProduct $product,AuthorizationService $a):JsonResponse
    {abort_unless($product->tenant_id===$this->tenant(),404);$this->allow($r,$a,$product->company_id);$d=$r->validate(['quantity'=>['required','regex:/^\\d+(\\.\\d{1,6})?$/'],'currency_id'=>'nullable|uuid','as_of'=>'nullable|date']);$date=$d['as_of']??now()->toDateString();$q=SupplierPurchasePriceListItem::where('tenant_id',$this->tenant())->where('supplier_product_id',$product->id)->whereHas('priceList',fn($x)=>$x->where('company_id',$product->company_id)->where('supplier_id',$product->supplier_id)->where('status','active')->whereDate('effective_from','<=',$date)->where(fn($z)=>$z->whereNull('effective_to')->orWhereDate('effective_to','>=',$date)))->where('minimum_quantity','<=',$d['quantity'])->where(fn($x)=>$x->whereNull('maximum_quantity')->orWhere('maximum_quantity','>=',$d['quantity']))->with('priceList')->get();if($q->count()===0)return response()->json(['data'=>['available'=>false,'reason'=>'No active supplier price applies to this quantity.']]);$prices=$q->pluck('unit_price')->unique();abort_if($prices->count()>1,409,'Conflicting active supplier prices apply.');$i=$q->sortByDesc('minimum_quantity')->first();return response()->json(['data'=>['available'=>true,'price'=>$i->unit_price,'currency_id'=>$i->priceList->currency_id,'source_type'=>'supplier_purchase_price_list','source_id'=>$i->priceList->id,'tier'=>['minimum'=>$i->minimum_quantity,'maximum'=>$i->maximum_quantity]]]);}
    public function contracts(Request $r,AuthorizationService $a):JsonResponse{$company=$r->string('company_id')->toString()?:null;$this->allow($r,$a,$company);$q=SupplierContract::where('tenant_id',$this->tenant())->with(['supplier','currency'])->when($company,fn($x)=>$x->where('company_id',$company))->latest();return response()->json(['data'=>$q->paginate(min(max($r->integer('per_page',25),10),100))]);}
    public function storeContract(Request $r,AuthorizationService $a,ProcurementNumberService $numbers,AuditLogger $audit):JsonResponse{$d=$r->validate(['company_id'=>'required|uuid','supplier_id'=>'required|uuid','name'=>'required|string|max:200','contract_type'=>'nullable|string|max:60','currency_id'=>'nullable|uuid','starts_at'=>'required|date','ends_at'=>'required|date|after_or_equal:starts_at','spend_ceiling'=>['nullable','regex:/^\\d+(\\.\\d{1,6})?$/'],'payment_terms'=>'nullable|string|max:200','delivery_terms'=>'nullable|string|max:4000','renewal_terms'=>'nullable|string|max:4000','notes'=>'nullable|string|max:5000']);$this->allow($r,$a,$d['company_id']);$t=$this->tenant();$s=Supplier::where('tenant_id',$t)->whereKey($d['supplier_id'])->firstOrFail();abort_unless($s->company_id===null||$s->company_id===$d['company_id'],422);$c=DB::transaction(function()use($d,$t,$r,$numbers){$c=SupplierContract::create([...$d,'tenant_id'=>$t,'number'=>$numbers->makeFor('SC',$t,$d['company_id'],null),'status'=>'draft','created_by'=>$r->user()->id]);SupplierContractVersion::create(['tenant_id'=>$t,'supplier_contract_id'=>$c->id,'version'=>1,'snapshot'=>$c->toArray(),'created_by'=>$r->user()->id]);return $c;});$audit->record($r,'supplier_contract.created',$t,$c);return response()->json(['data'=>$c->load(['supplier','currency'])],201);}
    public function activateContract(Request $r,SupplierContract $contract,AuthorizationService $a,AuditLogger $audit):JsonResponse{abort_unless($contract->tenant_id===$this->tenant(),404);$this->allow($r,$a,$contract->company_id);abort_unless($contract->status==='approved',422,'Only approved contracts can be activated.');$contract->update(['status'=>'active','activated_by'=>$r->user()->id,'activated_at'=>now()]);$audit->record($r,'supplier_contract.activated',$this->tenant(),$contract);return response()->json(['data'=>$contract]);}
    public function submitContract(Request $r,SupplierContract $contract,ApprovalService $approval,AuditLogger $audit):JsonResponse{abort_unless($contract->tenant_id===$this->tenant(),404);$this->allow($r,app(AuthorizationService::class),$contract->company_id);abort_unless($contract->status==='draft',422);$request=$approval->create(['tenant_id'=>$this->tenant(),'company_id'=>$contract->company_id,'requester_id'=>$r->user()->id,'scenario'=>'supplier_contract','amount'=>$contract->spend_ceiling??'0','document_type'=>SupplierContract::class,'document_id'=>$contract->id]);$contract->update(['status'=>'pending_approval','approval_request_id'=>$request->id]);$audit->record($r,'supplier_contract.submitted',$this->tenant(),$contract);return response()->json(['data'=>$contract->fresh()]);}
    public function approveContract(Request $r,SupplierContract $contract,ApprovalService $approval,AuditLogger $audit):JsonResponse{abort_unless($contract->tenant_id===$this->tenant(),404);$this->allow($r,app(AuthorizationService::class),$contract->company_id);abort_unless($contract->status==='pending_approval'&&$contract->approval_request_id,422);$d=$r->validate(['remarks'=>'nullable|string|max:2000']);$result=$approval->decide(ApprovalRequest::findOrFail($contract->approval_request_id),$r->user(),'approved',$d['remarks']??null);if($result->state==='approved')$contract->update(['status'=>'approved','approved_by'=>$r->user()->id,'approved_at'=>now()]);$audit->record($r,'supplier_contract.approval_decided',$this->tenant(),$contract,['state'=>$result->state]);return response()->json(['data'=>$contract->fresh()]);}
}
